import{_ as l,o as a,c as i,a4 as t}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"定投人生课堂搜索工具","description":"","frontmatter":{"date":"2023-05-01T07:00:03","title":"定投人生课堂搜索工具","categories":["定投人生课堂","定投搜索"],"tags":["定投人生课堂","定投搜索"]},"headers":[{"level":2,"title":"是什么","slug":"是什么","link":"#是什么","children":[]},{"level":2,"title":"如何使用","slug":"如何使用","link":"#如何使用","children":[]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[{"level":3,"title":"搜索不到结果","slug":"搜索不到结果","link":"#搜索不到结果","children":[]},{"level":3,"title":"数据如何获取","slug":"数据如何获取","link":"#数据如何获取","children":[]},{"level":3,"title":"数据何时更新","slug":"数据何时更新","link":"#数据何时更新","children":[]},{"level":3,"title":"功能是否会更新","slug":"功能是否会更新","link":"#功能是否会更新","children":[]},{"level":3,"title":"是否收费","slug":"是否收费","link":"#是否收费","children":[]},{"level":3,"title":"其他问题","slug":"其他问题","link":"#其他问题","children":[]}]},{"level":2,"title":"为什么","slug":"为什么","link":"#为什么","children":[]},{"level":2,"title":"感谢","slug":"感谢","link":"#感谢","children":[]}],"relativePath":"posts/course100/009.md","filePath":"posts/course100/009.md"}'),o={name:"posts/course100/009.md"};function r(n,e,h,s,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>「定投搜索」是一个免费的Mixin机器人，是「定投人生课堂」课程搜索工具，可以通过关键字检索「定投人生课堂」的课程内容，返回课程列表。</p><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li><p>登录Mixin，点击搜索「7000103414」，确认是「定投搜索」后添加机器人。</p></li><li><p>把搜索关键字发给该机器人，机器人会返回检索到的课程列表（结果最多10条课程）。</p><ul><li><p>支持多关键字，关键字之间使用空格分隔。</p></li><li><p>支持命令模式，使用<code>/</code>开启命令模式，当前只支持<code>/d</code>，表示返回课程详情，除了返回查询结果，还将一并返回查询结果的课程的卡片。如：<code>机会成本 /d</code>，可以在下面的图中看到返回结果。</p></li></ul></li><li><p>听课。</p><ul><li><p>从结果中复制课程标题到「定投人生课堂」搜索该课程，开始听课。</p></li><li><p>如果返回课程详情，直接点击卡片，授权后开始听课。</p></li></ul></li></ol><p><img src="https://assets.quill.im/mhxpas3dauszrwragc3p0pnjrrx5" alt="WechatIMG239.png"><img src="https://assets.quill.im/v011v1c9sryqm9ug0ndib8zbytp5" alt="WechatIMG238.png"></p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="搜索不到结果" tabindex="-1">搜索不到结果 <a class="header-anchor" href="#搜索不到结果" aria-label="Permalink to &quot;搜索不到结果&quot;">​</a></h3><blockquote><ul><li><p>技术原因，课程内容是语音的，使用的是语音识别技术，可能无法完全识别，可能识别错误，可能存在错别字，导致检索不到，另外中文需要分词，分词的结果可能会和我们的预期不一致，导致检索不到。</p></li><li><p>客观原因，没有导入课程数据，或者确实没有匹配的关键字。</p></li><li><p>可能的解决办法，调整关键字重新搜索。</p></li></ul></blockquote><h3 id="数据如何获取" tabindex="-1">数据如何获取 <a class="header-anchor" href="#数据如何获取" aria-label="Permalink to &quot;数据如何获取&quot;">​</a></h3><blockquote><p>手工整理。请不要找我索取课程数据，整理自己的课程笔记更重要，请听「学习的真相」的「必要关联」和「三个大脑」。</p></blockquote><h3 id="数据何时更新" tabindex="-1">数据何时更新 <a class="header-anchor" href="#数据何时更新" aria-label="Permalink to &quot;数据何时更新&quot;">​</a></h3><blockquote><p>课程数据是手动整理的，无法保证与课程内容的实时同步，只会不定期导入。</p></blockquote><h3 id="功能是否会更新" tabindex="-1">功能是否会更新 <a class="header-anchor" href="#功能是否会更新" aria-label="Permalink to &quot;功能是否会更新&quot;">​</a></h3><blockquote><p>目前功能基本可用，暂无功能计划，后续可能会增加命令模式的命令。</p><p>如果大家有新的想法，可以反馈。</p></blockquote><h3 id="是否收费" tabindex="-1">是否收费 <a class="header-anchor" href="#是否收费" aria-label="Permalink to &quot;是否收费&quot;">​</a></h3><blockquote><p>免费。如果觉得「定投搜索」工具确实对你有帮助，欢迎打赏，打赏本文即可。</p></blockquote><h3 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h3><blockquote><p>其他问题可以添加我的微信「Crazy_Airhead」，或Mixin号「1091586」，进行反馈和沟通。</p></blockquote><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>偶尔会想起一些模糊的课程内容，想重听一遍课程，但定投人生课堂只能按标题内容模糊搜索，于是只能凭记忆在Mixin中找，可能半天过去了还找不到自己想要的课程，这过程其实是挺痛苦的。在「定投人生课堂后花园」的里也会看到类似的查找课程的问题，于是有了做这个工具的想法。</p><p>之前为「且慢且慢且慢」写作群的战友提供过写作练习工具，但因为服务器和域名过期等原因，服务就中断了，非常抱歉。计划做这个工具的时候是想收费的，因为提供服务需要成本，实际做的过程中时候发现不需要公网服务器也可以提供服务，于是少了收费的欲望，本着服务战友的想法，于是决定免费开放服务。</p><p>此次提供的「定投搜索」工具，因为用了自家的NAS，理论上是可以长期服务战友们。如果「定投人生课堂」提供了更好的搜索功能，这个「定投搜索」工具也就没有存在的意义了，到时会停止服务。</p><p>在提供服务期间，如果出现无法使用的情况，请战友们及时反馈。</p><h2 id="感谢" tabindex="-1">感谢 <a class="header-anchor" href="#感谢" aria-label="Permalink to &quot;感谢&quot;">​</a></h2><p>刚开始有做「定投搜索」这个工具的想法时，小熊老师（微信号「huashichenxiong」）给了不少积极的反馈，让我开始实际编写这个工具；中间因为工作忙没怎么做，小熊老师又不停地鼓励；现在能提供服务，也是和小熊老师讨论Mixin机器人开发，打破自己的做微信公众号的思维定势（微信的机器人和微信公众号不是同一个物种），于是趁着放假时间赶紧完成剩下的工作。总之非常感谢小熊老师，如果没有小熊老师的鼓励，这个工具不知道什么时候才能完工。</p><p>感谢Mixin好友「字友与自由」，Mixin号「39488252」，帮忙解答了机器人无法接收消息的问题。他写了个Java版的SDK（<a href="https://github.com/tooonly/mixin-java-sdk%EF%BC%89%EF%BC%8C%E6%9C%89%E9%9C%80%E8%A6%81%E6%88%98%E5%8F%8B%E7%9A%84%E5%8F%AF%E4%BB%A5%E8%87%AA%E5%B7%B1%E8%8E%B7%E5%8F%96%E3%80%82" target="_blank" rel="noreferrer">https://github.com/tooonly/mixin-java-sdk）</a>，有需要战友的可以自己获取。</p>',26)])])}const b=l(o,[["render",r]]);export{u as __pageData,b as default};
